rows, cols = size of mat
dist = grid of -1, queue = empty
for each cell (r, c):
    if mat[r][c] == 0: dist[r][c] = 0, push (r, c)   (all sources go in before the BFS starts)
while the queue is not empty:
    (r, c) = pop the front
    for each of the four neighbours (nr, nc):
        skip if out of bounds
        skip if dist[nr][nc] != -1
        dist[nr][nc] = dist[r][c] + 1
        push (nr, nc)
return dist

graphs/05_prim_mst.algorithm:
build_adjacency(n, edges): adj = n empty lists; for (u, v, w) append (w, v) to adj[u], (w, u) to adj[v]
prim(n, edges, start):
    adj = build_adjacency(n, edges), in_tree = {}, total = 0, tree = []
    heap = [(0, start, start)]
    while the heap is not empty and len(in_tree) < n:
        (w, node, parent) = pop the smallest
        if node in in_tree: continue   (stale: node joined the tree through a cheaper edge)
        add node to in_tree
        if node != start: total = total + w, append (parent, node, w) to tree
        for (next_w, neighbour) in adj[node] not in in_tree: push (next_w, neighbour, node)
    return (total, tree)

graphs/06_dijkstra.algorithm:
build_adjacency(n, edges): adj = n empty lists; for (u, v, w) in edges append (v, w) to adj[u]
dijkstra(n, edges, source):
    adj = build_adjacency(n, edges)
    dist = {source: 0}, heap = [(0, source)]
    while the heap is not empty:
        (d, node) = pop the smallest
        if d > dist[node]: continue   (stale: a shorter route to node was found after this push)
        for (neighbour, w) in adj[node]:
            if d + w < dist.get(neighbour, infinity):
                dist[neighbour] = d + w
                push (d + w, neighbour)
    return dist
